      "explanation": "Phát biểu nào sau đây ĐÚNG về độ bao phủ quyết định (decision coverage)?\nĐáp án đúng: D. Decision coverage is a measure of the proportion of decision outcomes in the source code exercised by tests – Độ bao phủ quyết định là thước đo tỷ lệ các kết quả của các quyết định trong mã nguồn được thực thi bởi các ca kiểm thử.\nGiải thích: Decision Coverage kiểm tra xem mỗi kết quả của một quyết định (True/False) đã được thực thi hay chưa. Nó không đo số đường đi (paths) hay luồng nghiệp vụ mà đo tỷ lệ các kết quả quyết định được kiểm thử.",
